import jakarta.transaction.Transactional;
import java.util.*;

class TransferService {
    private final Map<String, Integer> balances = new LinkedHashMap<>(Map.of("A", 1000, "B", 500));

    @Transactional
    String transfer(String from, String to, int amount) {
        Integer f = balances.get(from), t = balances.get(to);
        if (f == null || t == null || amount <= 0 || f < amount) return "失敗";
        balances.put(from, f - amount);
        balances.put(to, t + amount);
        return "A=" + balances.get("A") + " B=" + balances.get("B");
    }
}

public class TxTransfer {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        TransferService service = new TransferService();
        System.out.println(service.transfer(sc.next(), sc.next(), sc.nextInt()));
    }
}

