import java.util.*;

public class TxShort {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<String> steps = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            steps.add(sc.next());
        }
        int commitAt = steps.indexOf("commit");
        for (int i = 0; i < steps.size(); i++) {
            String step = steps.get(i);
            boolean inTx = switch (step) {
                case "db-read", "db-insert", "db-update", "commit" -> true;
                default -> false;
            };
            boolean external = switch (step) {
                case "http-call", "send-mail", "notify" -> true;
                default -> false;
            };
            String mark = "";
            if (external && commitAt >= 0 && i < commitAt) {
                mark = " MOVE_AFTER_COMMIT";
            }
            System.out.println((inTx ? "[TX] " : "[OUT] ") + step + mark);
        }
    }
}

