import java.util.*;

record Result(int order, String item) { }

public class TxIdempotency {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        Map<String, Result> done = new LinkedHashMap<>();
        int sequence = 0;
        while (sc.hasNext()) {
            String key = sc.next(), item = sc.next();
            Result r = done.get(key);
            if (r == null) {
                r = new Result(++ sequence, item);
                done.put(key, r);
                System.out.println("created key=" + key + " order=" + r.order() + " item=" + r.item());
            } else System.out.println("replay key=" + key + " order=" + r.order() + " item=" + r.item());
        }
    }
}

